// Command tokens generates the design tokens of the macOS application and
// of the web UI from design/tokens.json, the one place they are defined.
//
//	go run ./scripts/tokens           writes the generated files
//	go run ./scripts/tokens -check    writes nothing; fails if one is stale
//
// The output depends only on the tokens: names are written in sorted order.
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

const (
	source   = "design/tokens.json"
	swiftOut = "macos/Sources/App/Tokens.swift"
	cssOut   = "web/src/tokens.css"
	header   = "Generated by scripts/tokens from design/tokens.json; do not edit."
)

// Color is an sRGB color with an alpha between 0 and 1. In the tokens it is
// "#rrggbb" or {"hex": "#rrggbb", "alpha": 0.5}.
type Color struct {
	RGB   uint32
	Alpha float64
}

var hexColor = regexp.MustCompile(`^#[0-9a-f]{6}$`)

func parseHex(s string) (uint32, error) {
	if !hexColor.MatchString(s) {
		return 0, fmt.Errorf("color %q is not #rrggbb in lower case", s)
	}
	v, err := strconv.ParseUint(s[1:], 16, 32)
	return uint32(v), err
}

func (c *Color) UnmarshalJSON(data []byte) error {
	var s string
	if json.Unmarshal(data, &s) == nil {
		rgb, err := parseHex(s)
		*c = Color{RGB: rgb, Alpha: 1}
		return err
	}
	var o struct {
		Hex   string   `json:"hex"`
		Alpha *float64 `json:"alpha"`
	}
	if err := strictUnmarshal(data, &o); err != nil {
		return fmt.Errorf("color %s is neither a string nor {hex, alpha}", bytes.TrimSpace(data))
	}
	rgb, err := parseHex(o.Hex)
	if err != nil {
		return err
	}
	if o.Alpha == nil || *o.Alpha < 0 || *o.Alpha > 1 {
		return fmt.Errorf("color %s needs an alpha between 0 and 1", bytes.TrimSpace(data))
	}
	*c = Color{RGB: rgb, Alpha: *o.Alpha}
	return nil
}

func (c Color) hex() string { return fmt.Sprintf("#%06x", c.RGB) }

func (c Color) css() string {
	if c.Alpha == 1 {
		return c.hex()
	}
	return fmt.Sprintf("rgba(%d, %d, %d, %s)", c.RGB>>16&0xff, c.RGB>>8&0xff, c.RGB&0xff, num(c.Alpha))
}

// Themed is a color of the interface in the light and the dark theme.
type Themed struct {
	Light Color `json:"light"`
	Dark  Color `json:"dark"`
}

func (t *Themed) UnmarshalJSON(data []byte) error {
	var o struct {
		Light *Color `json:"light"`
		Dark  *Color `json:"dark"`
	}
	if err := strictUnmarshal(data, &o); err != nil {
		return err
	}
	if o.Light == nil || o.Dark == nil {
		return errors.New("a color needs a light and a dark value")
	}
	*t = Themed{Light: *o.Light, Dark: *o.Dark}
	return nil
}

// Terminal is a terminal's default colors: the 16 ANSI colors are black to
// white, then their bright variants.
type Terminal struct {
	Background Color   `json:"background"`
	Foreground Color   `json:"foreground"`
	Cursor     Color   `json:"cursor"`
	Selection  Color   `json:"selection"`
	Palette    []Color `json:"palette"`
}

// Tokens is design/tokens.json.
type Tokens struct {
	Color    map[string]Themed `json:"color"`
	Status   map[string]Themed `json:"status"`
	Terminal struct {
		Light *Terminal `json:"light"`
		Dark  *Terminal `json:"dark"`
	} `json:"terminal"`
	Metric map[string]float64 `json:"metric"`
	Font   struct {
		Size map[string]float64 `json:"size"`
	} `json:"font"`
}

func strictUnmarshal(data []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return err
	}
	if _, err := dec.Token(); err != io.EOF {
		return errors.New("data after the JSON value")
	}
	return nil
}

var tokenName = regexp.MustCompile(`^[a-z][a-zA-Z0-9]*$`)

// parse reads and validates the tokens.
func parse(data []byte) (*Tokens, error) {
	var t Tokens
	if err := strictUnmarshal(data, &t); err != nil {
		return nil, err
	}
	groups := map[string][]string{
		"color": keys(t.Color), "status": keys(t.Status), "metric": keys(t.Metric), "font.size": keys(t.Font.Size),
	}
	for _, group := range keys(groups) {
		if len(groups[group]) == 0 {
			return nil, fmt.Errorf("%s has no tokens", group)
		}
		for _, name := range groups[group] {
			if !tokenName.MatchString(name) {
				return nil, fmt.Errorf("%s.%s: names are camelCase letters and digits", group, name)
			}
		}
	}
	for _, group := range []map[string]float64{t.Metric, t.Font.Size} {
		for name, v := range group {
			if v <= 0 {
				return nil, fmt.Errorf("%s must be positive", name)
			}
		}
	}
	for name, term := range map[string]*Terminal{"light": t.Terminal.Light, "dark": t.Terminal.Dark} {
		if term == nil {
			return nil, fmt.Errorf("terminal.%s is missing", name)
		}
		if len(term.Palette) != 16 {
			return nil, fmt.Errorf("terminal.%s.palette has %d colors, not 16", name, len(term.Palette))
		}
		for _, c := range append([]Color{term.Background, term.Foreground, term.Cursor, term.Selection}, term.Palette...) {
			if c.Alpha != 1 {
				return nil, fmt.Errorf("terminal.%s: terminal colors are opaque", name)
			}
		}
	}
	return &t, nil
}

func keys[V any](m map[string]V) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// num writes a number without a trailing ".0" or exponent.
func num(v float64) string { return strconv.FormatFloat(v, 'f', -1, 64) }

func upperFirst(s string) string { return strings.ToUpper(s[:1]) + s[1:] }

// kebab turns a camelCase name into kebab-case.
func kebab(s string) string {
	var b strings.Builder
	for i, r := range s {
		if r >= 'A' && r <= 'Z' {
			if i > 0 {
				b.WriteByte('-')
			}
			r += 'a' - 'A'
		}
		b.WriteRune(r)
	}
	return b.String()
}

// swift renders macos/Sources/App/Tokens.swift.
func swift(t *Tokens) []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, "// %s\n\nimport CoreGraphics\n\n", header)
	b.WriteString("/// The design tokens' raw values; `Theme` turns them into AppKit's types.\n")
	b.WriteString("enum Tokens {\n")
	b.WriteString("    /// A color in the light and the dark appearance: 0xRRGGBB and an alpha.\n")
	b.WriteString("    struct Color {\n        let light: UInt32, dark: UInt32\n        let lightAlpha: CGFloat, darkAlpha: CGFloat\n    }\n\n")
	b.WriteString("    /// A terminal's default colors as #rrggbb; the palette is the 16 ANSI colors.\n")
	b.WriteString("    struct Terminal {\n        let background, foreground, cursor, selection: String\n        let palette: [String]\n    }\n")
	themed := func(prefix string, m map[string]Themed) {
		b.WriteString("\n")
		for _, name := range keys(m) {
			c := m[name]
			fmt.Fprintf(&b, "    static let %s%s = Color(light: 0x%06x, dark: 0x%06x, lightAlpha: %s, darkAlpha: %s)\n",
				prefix, upperFirst(name), c.Light.RGB, c.Dark.RGB, num(c.Light.Alpha), num(c.Dark.Alpha))
		}
	}
	themed("color", t.Color)
	themed("status", t.Status)
	terminal := func(name string, term *Terminal) {
		fmt.Fprintf(&b, "\n    static let %s = Terminal(\n", name)
		fmt.Fprintf(&b, "        background: %q, foreground: %q, cursor: %q, selection: %q,\n",
			term.Background.hex(), term.Foreground.hex(), term.Cursor.hex(), term.Selection.hex())
		b.WriteString("        palette: [\n")
		for i := 0; i < 16; i += 8 {
			b.WriteString("           ")
			for _, c := range term.Palette[i : i+8] {
				fmt.Fprintf(&b, " %q,", c.hex())
			}
			b.WriteString("\n")
		}
		b.WriteString("        ]\n    )\n")
	}
	terminal("terminalDark", t.Terminal.Dark)
	terminal("terminalLight", t.Terminal.Light)
	numbers := func(prefix string, m map[string]float64) {
		b.WriteString("\n")
		for _, name := range keys(m) {
			fmt.Fprintf(&b, "    static let %s%s: CGFloat = %s\n", prefix, upperFirst(name), num(m[name]))
		}
	}
	numbers("metric", t.Metric)
	numbers("fontSize", t.Font.Size)
	b.WriteString("}\n")
	return b.Bytes()
}

// css renders web/src/tokens.css in the form Prettier keeps. The dark
// theme is the default and <html data-theme="light"> selects the light
// one, as in web/src/styles.css.
func css(t *Tokens) []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, "/* %s */\n", header)
	block := func(selector string, light bool) {
		pick := func(c Themed) Color {
			if light {
				return c.Light
			}
			return c.Dark
		}
		fmt.Fprintf(&b, "%s {\n", selector)
		for _, name := range keys(t.Color) {
			fmt.Fprintf(&b, "  --ds-color-%s: %s;\n", kebab(name), pick(t.Color[name]).css())
		}
		for _, name := range keys(t.Status) {
			fmt.Fprintf(&b, "  --ds-status-%s: %s;\n", kebab(name), pick(t.Status[name]).css())
		}
		term := t.Terminal.Dark
		if light {
			term = t.Terminal.Light
		}
		fmt.Fprintf(&b, "  --ds-terminal-background: %s;\n", term.Background.css())
		fmt.Fprintf(&b, "  --ds-terminal-foreground: %s;\n", term.Foreground.css())
		fmt.Fprintf(&b, "  --ds-terminal-cursor: %s;\n", term.Cursor.css())
		fmt.Fprintf(&b, "  --ds-terminal-selection: %s;\n", term.Selection.css())
		for i, c := range term.Palette {
			fmt.Fprintf(&b, "  --ds-terminal-ansi-%d: %s;\n", i, c.css())
		}
		if !light {
			// Lengths do not change with the theme.
			for _, name := range keys(t.Metric) {
				fmt.Fprintf(&b, "  --ds-metric-%s: %spx;\n", kebab(name), num(t.Metric[name]))
			}
			for _, name := range keys(t.Font.Size) {
				fmt.Fprintf(&b, "  --ds-font-size-%s: %spx;\n", kebab(name), num(t.Font.Size[name]))
			}
		}
		b.WriteString("}\n")
	}
	block(":root", false)
	block(":root[data-theme='light']", true)
	return b.Bytes()
}

// generate returns the generated files by their path under the repository.
func generate(data []byte) (map[string][]byte, error) {
	t, err := parse(data)
	if err != nil {
		return nil, err
	}
	return map[string][]byte{swiftOut: swift(t), cssOut: css(t)}, nil
}

// run generates the files under root; with check it writes nothing and
// reports the files that differ from what would be generated.
func run(root string, check bool) error {
	data, err := os.ReadFile(filepath.Join(root, source))
	if err != nil {
		return err
	}
	files, err := generate(data)
	if err != nil {
		return fmt.Errorf("%s: %w", source, err)
	}
	var stale []string
	for _, name := range keys(files) {
		path := filepath.Join(root, name)
		if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, files[name]) {
			continue
		}
		if check {
			stale = append(stale, name)
			continue
		}
		if err := os.WriteFile(path, files[name], 0o644); err != nil {
			return err
		}
	}
	if len(stale) > 0 {
		return fmt.Errorf("stale: %s (run `make tokens`)", strings.Join(stale, ", "))
	}
	return nil
}

func main() {
	check := flag.Bool("check", false, "write nothing; fail if a generated file is stale")
	root := flag.String("root", ".", "the repository")
	flag.Parse()
	if err := run(*root, *check); err != nil {
		fmt.Fprintln(os.Stderr, "tokens:", err)
		os.Exit(1)
	}
}
